import React, { useState, useEffect, useRef, useMemo } from "https://esm.sh/react@18.2.0";
import { createRoot } from "https://esm.sh/react-dom@18.2.0/client";
import htm from "https://esm.sh/htm@3.1.1";
const html = htm.bind(React.createElement);

/* Correction Rules builder. The rule lives in this widget's own state and goes
   out with triggerEvent (onRun / onPreview); the model only brings data in. */

let seq = 1;
const uid = () => "n" + (seq++);
const LETTERS = ["A", "B", "C", "D"];
const CMP = ["eq", "neq", "gt", "gte", "lt", "lte"];
const NOVAL = ["empty", "not_empty"];
const kind = t => t === "number" ? "n" : t === "date" ? "d" : "t";
const iso = d => d.toISOString().slice(0, 10);
function defaultDates() {
  const to = new Date(); const from = new Date(); from.setFullYear(from.getFullYear() - 1);
  return { dateFrom: iso(from), dateTo: iso(to) };
}
const blankRule = () => Object.assign({ match: "ALL", conditions: [], aliases: [], cross: [], changes: [] }, defaultDates());
const newCond = field => ({ id: uid(), field: field || "", op: "", value: "", mode: "value", valueField: "" });
/* fields a change can set */
const CHANGE_FIELDS = [{ id: "uom", label: "Unit of measure" }, { id: "code", label: "Observation type" }];
const newChange = target => ({ id: uid(), target: target || "A", field: "uom", value: "" });
/* demand observation types: the Demand units mockup's 20, plus the demand codes
   seen in the line items data (BILLEDDEM_USE, GENDEM_*, INFO_GENDEM_USE) */
const DEMAND_CODES = ["BILLEDDEM_MIDPEAK", "BILLEDDEM_OFFPEAK", "BILLEDDEM_ONPEAK", "BILLEDDEM_SHDPEAK", "BILLEDDEM_SUPER",
  "BILLEDGENDEM_USE", "DEM_USE", "DEM_ONPEAK", "DEM_MIDPEAK", "DEM_OFFPEAK", "DEM_SHDPEAK", "DEM_SUPPEAK", "DEM_SUPOFFPEAK",
  "CRFDEM_USE", "INFO_DEMAND", "DEM_CHG", "BILLEDREACTDEM_USE", "REACTDEM_OFFPK", "REACTDEM_ONPK", "REACT_DEM",
  "BILLEDDEM_USE", "GENDEM_USE", "GENDEM_ONPEAK", "GENDEM_MIDPEAK", "GENDEM_OFFPEAK", "INFO_GENDEM_USE"];
const MATCH_OPTS = [{ value: "ALL", label: "Match ALL conditions" }, { value: "ANY", label: "Match ANY condition" }];
const GROUP_MATCH_OPTS = [{ value: "ALL", label: "ALL of these" }, { value: "ANY", label: "ANY of these" }];
const MODE_OPTS = [{ value: "exists", label: "must exist on the bill" }, { value: "not_exists", label: "must NOT exist on the bill" }];

/* rebuild ids on a rule loaded from the store */
function withIds(r) {
  const fix = n => n.conditions ? Object.assign({}, n, { id: uid(), conditions: n.conditions.map(fix) }) : Object.assign({}, n, { id: uid() });
  const out = fix(Object.assign(blankRule(), r || {}));
  out.aliases = (r && r.aliases || []).map(a => Object.assign({ match: "ALL" }, a, { id: uid(), conditions: (a.conditions || []).map(fix) }));
  out.cross = (r && r.cross || []).map(fix);
  out.changes = (r && r.changes || []).map(c => Object.assign({}, c, { id: uid() }));
  return out;
}

function useModel() {
  const [m, setM] = useState(appsmith.model || {});
  useEffect(() => {
    const up = () => setM(Object.assign({}, appsmith.model || {}));
    up();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(up);
    const t = setInterval(up, 500);
    return () => clearInterval(t);
  }, []);
  return m;
}

function useOutside(ref, onOut) {
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) onOut(); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
}

/* ---------- one dropdown for everything: themed, searchable ---------- */

/* options: [{ value, label, count? }]. free: typed text can be used as the value. */
function Select({ value, options, onChange, placeholder, disabled, search, free, className, mono }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const [hi, setHi] = useState(0);
  const ref = useRef(null);
  const listRef = useRef(null);
  useOutside(ref, () => setOpen(false));
  const canSearch = search !== undefined ? search : (free || options.length > 8);
  const cur = options.find(o => o.value === value);
  const label = cur ? cur.label : (value !== "" && value != null ? String(value) : "");
  const needle = q.trim().toLowerCase();
  const exact = o => String(o.value).toLowerCase() === needle || String(o.label).toLowerCase() === needle;
  // an exact match goes first, so typing "KW" + Enter picks KW, not KWH
  const shown = !needle ? options : options.filter(o => (o.label + " " + o.value).toLowerCase().includes(needle))
    .sort((a, b) => exact(b) - exact(a));
  const useTyped = free && q.trim() && !options.some(o => o.value === q.trim());
  const rows = (useTyped ? [{ value: q.trim(), label: "Use “" + q.trim() + "”", typed: true }] : []).concat(shown.slice(0, 500));
  const pick = o => { onChange(o.value); setOpen(false); setQ(""); };
  const toggle = () => { if (disabled) return; setOpen(!open); setQ(""); setHi(Math.max(0, options.findIndex(o => o.value === value))); };
  const key = e => {
    if (e.key === "ArrowDown") { e.preventDefault(); setHi(Math.min(hi + 1, rows.length - 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setHi(Math.max(hi - 1, 0)); }
    else if (e.key === "Enter") { e.preventDefault(); if (rows[hi]) pick(rows[hi]); }
    else if (e.key === "Escape") setOpen(false);
  };
  useEffect(() => {
    const el = listRef.current && listRef.current.children[hi];
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [hi, open]);
  return html`<div className=${"sel " + (className || "")} ref=${ref}>
    <button type="button" className=${"inp sel-btn" + (label ? "" : " ph") + (mono ? " mono" : "")} disabled=${disabled}
      onClick=${toggle} onKeyDown=${e => { if (!open && (e.key === "ArrowDown" || e.key === "Enter")) { e.preventDefault(); toggle(); } else if (open) key(e); }}>
      <span className="sel-txt">${label || placeholder || "Choose…"}</span><span className="chev">▾</span>
    </button>
    ${open && html`<div className="pop">
      ${canSearch && html`<input className="inp" autoFocus placeholder=${free ? "Search or type a value" : "Search"} value=${q}
        onInput=${e => { setQ(e.target.value); setHi(0); }} onKeyDown=${key} />`}
      <div className="pop-list" ref=${listRef}>
        ${rows.map((o, i) => html`<div key=${(o.typed ? "~" : "") + o.value} className=${"pop-row" + (i === hi ? " hi" : "") + (o.value === value ? " on" : "")}
            onMouseEnter=${() => setHi(i)} onMouseDown=${e => { e.preventDefault(); pick(o); }}>
          <span className=${mono && !o.typed ? "mono" : ""}>${o.label}</span>${o.count != null && html`<span className="cnt">${o.count.toLocaleString()}</span>`}
        </div>`)}
        ${!rows.length && html`<div className="muted pad-s">No matches</div>`}
      </div>
    </div>`}
  </div>`;
}

function MultiPick({ options, value, onChange }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const ref = useRef(null);
  useOutside(ref, () => setOpen(false));
  const sel = Array.isArray(value) ? value : [];
  const shown = options.filter(o => !q || o.value.toLowerCase().includes(q.toLowerCase()));
  const typed = q.trim() && !options.some(o => o.value === q.trim()) && !sel.includes(q.trim()) ? q.trim() : "";
  const toggle = v => onChange(sel.includes(v) ? sel.filter(x => x !== v) : sel.concat([v]));
  const label = !sel.length ? "" : sel.length <= 2 ? sel.join(", ") : sel.length + " selected";
  return html`<div className="sel" ref=${ref}>
    <button type="button" className=${"inp sel-btn" + (sel.length ? "" : " ph")} onClick=${() => setOpen(!open)}>
      <span className="sel-txt">${label || "Choose values…"}</span><span className="chev">▾</span></button>
    ${open && html`<div className="pop">
      <input className="inp" placeholder="Search or type a value" value=${q} onInput=${e => setQ(e.target.value)} autoFocus
        onKeyDown=${e => { if (e.key === "Enter" && typed) { e.preventDefault(); toggle(typed); setQ(""); } }} />
      <div className="pop-acts">
        <a onClick=${() => onChange(Array.from(new Set(sel.concat(shown.map(o => o.value)))))}>Select shown (${shown.length})</a>
        <a onClick=${() => onChange([])}>Clear</a>
      </div>
      <div className="pop-list">
        ${typed && html`<label className="pop-row"><input type="checkbox" checked=${false} onChange=${() => { toggle(typed); setQ(""); }} /><span>Add “${typed}”</span></label>`}
        ${sel.filter(v => !options.some(o => o.value === v)).map(v => html`<label key=${"x" + v} className="pop-row">
          <input type="checkbox" checked=${true} onChange=${() => toggle(v)} /><span className="mono">${v}</span></label>`)}
        ${shown.slice(0, 500).map(o => html`<label key=${o.value} className="pop-row">
          <input type="checkbox" checked=${sel.includes(o.value)} onChange=${() => toggle(o.value)} />
          <span className="mono">${o.value}</span><span className="cnt">${o.n.toLocaleString()}</span></label>`)}
        ${!shown.length && !typed && html`<div className="muted pad-s">No values</div>`}
      </div>
    </div>`}
  </div>`;
}

const asOpts = vals => vals.map(o => ({ value: o.value, label: o.value, count: o.n }));

function ValueEditor({ c, f, options, compareFields, onChange }) {
  if (!f || !c.op || NOVAL.includes(c.op)) return html`<div className="val-empty"></div>`;
  const set = p => onChange(Object.assign({}, c, p));
  const canField = CMP.includes(c.op) && compareFields.length > 0;
  const modeBtn = canField && html`<button type="button" className="mode" title="Compare with a value or with another field"
      onClick=${() => set({ mode: c.mode === "field" ? "value" : "field", value: "", valueField: "" })}>${c.mode === "field" ? "field" : "value"}</button>`;
  if (c.mode === "field" && canField) {
    return html`<div className="val">${modeBtn}
      <${Select} value=${c.valueField} placeholder="Choose field…" search=${true}
        options=${compareFields.map(x => ({ value: x.ref, label: x.label }))} onChange=${v => set({ valueField: v })} /></div>`;
  }
  const inType = f.type === "number" ? "number" : f.type === "date" ? "date" : "text";
  if (c.op === "in" || c.op === "not_in") {
    return html`<div className="val"><${MultiPick} options=${options} value=${c.value} onChange=${v => set({ value: v })} /></div>`;
  }
  if (c.op === "between") {
    const v = Array.isArray(c.value) ? c.value : ["", ""];
    return html`<div className="val two">
      <input className="inp" type=${inType} value=${v[0] || ""} onInput=${e => set({ value: [e.target.value, v[1] || ""] })} />
      <span className="muted">and</span>
      <input className="inp" type=${inType} value=${v[1] || ""} onInput=${e => set({ value: [v[0] || "", e.target.value] })} /></div>`;
  }
  if (inType === "text" && options.length && (c.op === "eq" || c.op === "neq")) {
    return html`<div className="val">${modeBtn}
      <${Select} value=${Array.isArray(c.value) ? "" : c.value} placeholder="Choose a value…" free=${true} mono=${true}
        options=${asOpts(options)} onChange=${v => set({ value: v })} /></div>`;
  }
  return html`<div className="val">${modeBtn}
    <input className="inp" type=${inType} placeholder="Enter value" value=${Array.isArray(c.value) ? "" : c.value}
      onInput=${e => set({ value: e.target.value })} /></div>`;
}

/* ---------- condition rows and groups ---------- */

function CondRow({ c, lead, fieldList, ctx, onChange, onRemove }) {
  const f = ctx.fieldOf(c.field);
  const ops = f ? ctx.ops[f.type] : [];
  const set = p => onChange(Object.assign({}, c, p));
  const compareFields = f ? fieldList.filter(x => x.ref !== c.field && kind(x.f.type) === kind(f.type)) : [];
  return html`<div className="row">
    <span className="lead">${lead}</span>
    <${Select} value=${c.field} placeholder="Choose field…" search=${true}
      options=${fieldList.map(x => ({ value: x.ref, label: x.label }))}
      onChange=${v => { const nf = ctx.fieldOf(v); set({ field: v, op: nf ? ctx.ops[nf.type][0] : "", value: "", mode: "value", valueField: "" }); }} />
    <${Select} value=${c.op} placeholder="Operator" disabled=${!f} search=${false}
      options=${ops.map(o => ({ value: o, label: ctx.opLabels[o] }))}
      onChange=${op => {
        const multi = op === "in" || op === "not_in", two = op === "between";
        const was = c.op === "in" || c.op === "not_in" || c.op === "between";
        set({ op, value: multi ? [] : two ? ["", ""] : was ? "" : c.value, mode: CMP.includes(op) ? c.mode : "value" });
      }} />
    <${ValueEditor} c=${c} f=${f} options=${f && f.options ? (ctx.values[f.options] || []) : []} compareFields=${compareFields} onChange=${onChange} />
    <button type="button" className="x" title="Remove condition" onClick=${onRemove}>×</button>
  </div>`;
}

function Group({ node, depth, fieldList, ctx, onChange, onRemove, defaultField }) {
  const kids = node.conditions || [];
  const setKids = k => onChange(Object.assign({}, node, { conditions: k }));
  const joiner = node.match === "ANY" ? "OR" : "AND";
  const fresh = () => {
    const c = newCond(defaultField);
    const f = ctx.fieldOf(defaultField);
    if (f) c.op = ctx.ops[f.type][0];
    return c;
  };
  return html`<div className=${depth ? "group" : "group-root"}>
    ${depth > 0 && html`<div className="group-head">
      <span className="muted small">Group: match</span>
      <${Select} className="w-sm" value=${node.match} search=${false} options=${GROUP_MATCH_OPTS}
        onChange=${v => onChange(Object.assign({}, node, { match: v }))} />
      <span className="grow"></span>
      <button type="button" className="btn ghost danger sm" onClick=${onRemove}>Remove group</button></div>`}
    ${kids.map((k, i) => k.conditions
      ? html`<div key=${k.id} className="row-wrap"><span className="lead">${i ? joiner : "Where"}</span>
          <${Group} node=${k} depth=${depth + 1} fieldList=${fieldList} ctx=${ctx} defaultField=${defaultField}
            onChange=${nk => setKids(kids.map(x => x.id === k.id ? nk : x))} onRemove=${() => setKids(kids.filter(x => x.id !== k.id))} /></div>`
      : html`<${CondRow} key=${k.id} c=${k} lead=${i ? joiner : "Where"} fieldList=${fieldList} ctx=${ctx}
          onChange=${nk => setKids(kids.map(x => x.id === k.id ? nk : x))} onRemove=${() => setKids(kids.filter(x => x.id !== k.id))} />`)}
    <div className="adds">
      <button type="button" className="btn ghost sm" onClick=${() => setKids(kids.concat([fresh()]))}>+ Add condition</button>
      ${depth < 3 && html`<button type="button" className="btn ghost sm" onClick=${() => setKids(kids.concat([{ id: uid(), match: node.match === "ANY" ? "ALL" : "ANY", conditions: [fresh()] }]))}>+ Add group</button>`}
    </div>
  </div>`;
}

/* ---------- presets (built from this customer's real values) ---------- */

function presets(values) {
  const codes = (values.code || []).map(o => o.value);
  const uoms = (values.uom || []).map(o => o.value);
  const kwh = uoms.find(u => /^kwh$/i.test(u)) || "KWH";
  const known = DEMAND_CODES.filter(c => codes.includes(c));
  const dem = known.length ? known : codes.length ? codes.filter(c => /DEM/i.test(c)) : DEMAND_CODES;
  return [
    { key: "dem", label: "Demand units: demand types labelled kWh", rule: { aliases: [{ name: "A", mode: "exists", match: "ALL", conditions: [
      Object.assign(newCond("A.code"), { op: "in", value: dem }),
      Object.assign(newCond("A.uom"), { op: "eq", value: kwh })] }],
      changes: [newChange("A")] } },
    { key: "gen", label: "Two generation lines with the same quantity", rule: { aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [Object.assign(newCond("A.code"), { op: "contains", value: "GEN" })] },
      { name: "B", mode: "exists", match: "ALL", conditions: [Object.assign(newCond("B.code"), { op: "contains", value: "GEN" })] }],
      cross: [Object.assign(newCond("A.usage"), { op: "eq", mode: "field", valueField: "B.usage" })] } },
    { key: "nouse", label: "Bills with no usage-information line", rule: { aliases: [{ name: "A", mode: "not_exists", match: "ALL", conditions: [
      Object.assign(newCond("A.category"), { op: "eq", value: "Usage Information" })] }] } },
    { key: "late", label: "Late fees over $50", rule: { aliases: [{ name: "A", mode: "exists", match: "ALL", conditions: [
      Object.assign(newCond("A.code"), { op: "eq", value: "LATEFEE" }),
      Object.assign(newCond("A.charge"), { op: "gt", value: "50" })] }] } },
    { key: "big", label: "Line total over $500 and more than 10 lines", rule: { match: "ALL", conditions: [
      Object.assign(newCond("bill.total_charges"), { op: "gt", value: "500" }),
      Object.assign(newCond("bill.line_count"), { op: "gt", value: "10" })] } }
  ];
}

/* ---------- results ---------- */

const money = v => v == null || v === "" ? "" : Number(v).toLocaleString(undefined, { style: "currency", currency: "USD" });
const COLS = [
  { k: "bill_id", l: "Bill ID" }, { k: "statement_date", l: "Statement date" }, { k: "utility", l: "Utility" },
  { k: "vendor", l: "Vendor" }, { k: "account", l: "Account" }, { k: "location_name", l: "Location" },
  { k: "line_count", l: "Lines", num: true }, { k: "total_charges", l: "Line total", num: true, fmt: money }
];
const OBS_COLS = [
  { k: "bill_id", l: "Bill ID" }, { k: "statement_date", l: "Statement date" }, { k: "vendor", l: "Vendor" },
  { k: "code", l: "Observation type", mono: true }, { k: "uom", l: "UOM" }, { k: "usage", l: "Quantity", num: true },
  { k: "charge", l: "Charge", num: true, fmt: money }, { k: "description", l: "Description" }
];
function toCsv(cols, rows) {
  const q = v => { const s = v == null ? "" : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  return [cols.map(c => c.l).join(",")].concat(rows.map(r => cols.map(c => q(c.get ? c.get(r) : r[c.k])).join(","))).join("\n");
}
const cellText = (c, r) => c.fmt ? c.fmt(r[c.k]) : (r[c.k] == null ? "" : String(r[c.k]));

function Table({ cols, rows, keyOf }) {
  return html`<div className="tbl-wrap"><table className="tbl">
    <thead><tr>${cols.map(c => html`<th key=${c.k} className=${c.num ? "num" : ""}>${c.l}</th>`)}</tr></thead>
    <tbody>${rows.map((r, i) => html`<tr key=${keyOf(r, i)}>${cols.map(c => html`<td key=${c.k} className=${(c.num ? "num " : "") + (c.mono ? "mono" : "")}>${
      c.k === "bill_id" ? html`<a className="link" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: r.bill_id })}>${r.bill_id}</a>`
        : c.render ? c.render(r) : cellText(c, r)}</td>`)}</tr>`)}</tbody>
  </table></div>`;
}

function Elapsed() {
  const [s, setS] = useState(0);
  useEffect(() => { const t0 = Date.now(); const t = setInterval(() => setS(Math.floor((Date.now() - t0) / 1000)), 1000); return () => clearInterval(t); }, []);
  return html`<span>${s}s${s >= 20 ? " · a large customer or a long date range takes longer; it stops at about 55s" : ""}</span>`;
}

function Results({ res, running, changes }) {
  const [tab, setTab] = useState("obs");
  if (running || (res && res.loading)) return html`<div className="card"><div className="muted pad">Searching bills… <${Elapsed} /></div></div>`;
  if (!res) return null;
  if (res.error) return html`<div className="card"><div className="err pad">${res.error}</div></div>`;
  const rows = res.rows || [], obsRows = res.obsRows || [];
  const hasObs = !!res.target;
  const view = hasObs ? tab : "bills";
  // preview columns: one "New ..." column per change on the listed observation
  const live = (changes || []).filter(c => c.target === res.target);
  const newCols = live.map(c => {
    const f = CHANGE_FIELDS.find(x => x.id === c.field) || CHANGE_FIELDS[0];
    return {
      k: "new_" + c.id, l: "New " + (f.id === "uom" ? "UOM" : f.label.toLowerCase()),
      get: () => c.value || "",
      render: r => !c.value ? html`<span className="muted">Not selected</span>`
        : String(r[f.id] || "") === c.value ? html`<span className="muted">${c.value} (no change)</span>`
        : html`<span className="new">${c.value}</span>`
    };
  });
  const cols = view === "obs" ? OBS_COLS.concat(newCols) : COLS;
  const list = view === "obs" ? obsRows : rows;
  const total = view === "obs" ? res.obsTotal || 0 : res.total;
  const noun = view === "obs" ? "observation" : "bill";
  return html`<div className="card">
    <div className="card-head">
      ${hasObs ? html`<div className="tabs">
        <button type="button" className=${"tab" + (view === "obs" ? " on" : "")} onClick=${() => setTab("obs")}>Matching observations (${res.target}) · ${(res.obsTotal || 0).toLocaleString()}</button>
        <button type="button" className=${"tab" + (view === "bills" ? " on" : "")} onClick=${() => setTab("bills")}>Bills · ${res.total.toLocaleString()}</button>
      </div>` : html`<h2>Matching bills</h2>`}
      <span className="pill">${total.toLocaleString()} ${noun}${total === 1 ? "" : "s"}${total > list.length ? " · showing newest " + list.length : ""}</span>
      <span className="muted small">${(res.ms / 1000).toFixed(1)}s</span>
      <span className="grow"></span>
      ${list.length > 0 && html`<button type="button" className="btn ghost" onClick=${() => appsmith.triggerEvent("onDownload", {
        csv: toCsv(cols, list), fileName: view === "obs" ? "matching-observations.csv" : "matching-bills.csv" })}>Download CSV</button>`}
    </div>
    ${view === "obs" && live.length > 0 && html`<div className="muted small">Preview only: nothing is changed in UBM. Values stay the same; only the field shown changes.</div>`}
    ${!list.length ? html`<div className="muted pad">No ${noun}s match these conditions in this date range.</div>`
      : html`<${Table} cols=${cols} rows=${list} keyOf=${(r, i) => view === "obs" ? r.bill_id + "-" + i : r.bill_id} />`}
  </div>`;
}

/* ---------- app ---------- */

function App() {
  const m = useModel();
  const F = m.fields || { bill: [], obs: [], ops: {}, opLabels: {} };
  const [rule, setRule] = useState(blankRule);
  const [showSql, setShowSql] = useState(false);
  const loaded = useRef(false);

  useEffect(() => {
    if (loaded.current || !m.fields) return;
    loaded.current = true;
    if (m.savedRule) setRule(withIds(m.savedRule));
  }, [m.fields, m.savedRule]);

  const values = useMemo(() => {
    const out = {};
    (m.values || []).forEach(r => {
      if (r.value == null || r.value === "") return;
      (out[r.field] = out[r.field] || []).push({ value: String(r.value), n: Number(r.n) || 0 });
    });
    Object.keys(out).forEach(k => out[k].sort((a, b) => b.n - a.n));
    return out;
  }, [m.values]);

  const billFields = F.bill.map(f => ({ ref: "bill." + f.id, label: f.label, f }));
  const aliasFields = name => F.obs.map(f => ({ ref: name + "." + f.id, label: name + " · " + f.label, f }));
  const ctx = {
    ops: F.ops, opLabels: F.opLabels, values,
    fieldOf: ref => {
      const s = String(ref || ""), i = s.indexOf(".");
      if (i < 0) return null;
      return (s.slice(0, i) === "bill" ? F.bill : F.obs).find(f => f.id === s.slice(i + 1)) || null;
    }
  };
  const set = p => setRule(Object.assign({}, rule, p));
  const present = rule.aliases.filter(a => a.mode !== "not_exists");
  const crossFields = [].concat(...present.map(a => aliasFields(a.name)));
  const keepFor = name => c => [c.field, c.mode === "field" ? c.valueField : ""].every(r => !r || !r.startsWith(name + "."));

  const addAlias = () => {
    const name = LETTERS.find(l => !rule.aliases.some(a => a.name === l));
    if (!name) return;
    const c = Object.assign(newCond(name + ".code"), { op: "eq" });
    set({ aliases: rule.aliases.concat([{ id: uid(), name, mode: "exists", match: "ALL", conditions: [c] }]) });
  };
  const send = ev => {
    if (ev === "onPreview") setShowSql(true);
    appsmith.triggerEvent(ev, { rule: JSON.parse(JSON.stringify(rule)) });
  };
  const sqlInfo = m.sqlInfo || {};
  const res = m.result;
  const err = sqlInfo.error || (res && res.error) || "";
  const running = !!m.running || !!(res && res.loading);
  const countConds = n => {
    let t = 0;
    const stack = [n];
    while (stack.length) (stack.pop().conditions || []).forEach(k => { if (k.conditions) stack.push(k); else if (k.field) t++; });
    return t;
  };
  const count = countConds(rule) + rule.aliases.reduce((t, a) => t + countConds(a), 0) + rule.cross.filter(c => c.field).length;
  const presetList = presets(values);

  return html`<div className="page">
    <div className="title-row">
      <div><h1>Find bills</h1><div className="muted">Combine bill fields and line-item observations. Observations A, B… must be lines on the same bill.</div></div>
      <span className="grow"></span>
      <${Select} className="w-preset" value="" placeholder="Start from an example…" search=${false}
        options=${presetList.map(p => ({ value: p.key, label: p.label }))}
        onChange=${k => {
          const p = presetList.find(x => x.key === k);
          if (p) setRule(Object.assign(withIds(p.rule), { dateFrom: rule.dateFrom, dateTo: rule.dateTo }));
        }} />
    </div>

    <div className="card">
      <div className="card-head">
        <h2>Bill conditions</h2>
        <span className="grow"></span>
        <label className="muted small">Bills dated</label>
        <input className="inp date" type="date" value=${rule.dateFrom} onInput=${e => set({ dateFrom: e.target.value })} />
        <span className="muted small">to</span>
        <input className="inp date" type="date" value=${rule.dateTo} onInput=${e => set({ dateTo: e.target.value })} />
        <${Select} className="w-match" value=${rule.match} search=${false} options=${MATCH_OPTS} onChange=${v => set({ match: v })} />
      </div>
      ${!rule.conditions.length && html`<div className="muted small hint">No bill conditions: every bill in the date range qualifies.</div>`}
      <${Group} node=${rule} depth=${0} fieldList=${billFields} ctx=${ctx} defaultField=""
        onChange=${n => set({ conditions: n.conditions })} />
    </div>

    <div className="card">
      <div className="card-head"><h2>Observations on the same bill</h2>
        <span className="muted small">Each observation is one line item. Its conditions must all match that one line.</span></div>
      ${rule.aliases.map(a => {
        const setA = p => set({ aliases: rule.aliases.map(x => x.id === a.id ? Object.assign({}, x, p) : x) });
        const fl = aliasFields(a.name).concat(billFields);
        return html`<div key=${a.id} className="alias">
          <div className="alias-head">
            <span className="badge">${a.name}</span>
            <${Select} className="w-mode" value=${a.mode} search=${false} options=${MODE_OPTS} onChange=${mode => {
              const nextAliases = rule.aliases.map(x => x.id === a.id ? Object.assign({}, x, { mode }) : x);
              set({ aliases: nextAliases,
                cross: mode === "not_exists" ? rule.cross.filter(keepFor(a.name)) : rule.cross,
                changes: mode === "not_exists" ? rule.changes.filter(x => x.target !== a.name) : rule.changes });
            }} />
            <span className="muted small">match</span>
            <${Select} className="w-sm" value=${a.match || "ALL"} search=${false} options=${GROUP_MATCH_OPTS} onChange=${v => setA({ match: v })} />
            <span className="grow"></span>
            <button type="button" className="btn ghost danger sm" onClick=${() => set({ aliases: rule.aliases.filter(x => x.id !== a.id),
              cross: rule.cross.filter(keepFor(a.name)), changes: rule.changes.filter(x => x.target !== a.name) })}>Remove ${a.name}</button>
          </div>
          <${Group} node=${a} depth=${0} fieldList=${fl} ctx=${ctx} defaultField=${a.name + ".code"}
            onChange=${n => setA({ conditions: n.conditions })} />
        </div>`;
      })}
      <div className="adds">
        ${rule.aliases.length < 4 && html`<button type="button" className="btn ghost" onClick=${addAlias}>+ Add observation</button>`}
      </div>
    </div>

    ${present.length > 0 && html`<div className="card">
      <div className="card-head"><h2>Compare observations</h2>
        <span className="muted small">For example A · Quantity is equal to B · Quantity. All comparisons must hold.</span></div>
      ${rule.cross.map((c, i) => html`<${CondRow} key=${c.id} c=${c} lead=${i ? "AND" : "If"} fieldList=${crossFields} ctx=${ctx}
        onChange=${nc => set({ cross: rule.cross.map(x => x.id === c.id ? nc : x) })}
        onRemove=${() => set({ cross: rule.cross.filter(x => x.id !== c.id) })} />`)}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ cross: rule.cross.concat([newCond()]) })}>+ Add comparison</button></div>
    </div>`}

    ${present.length > 0 && html`<div className="card">
      <div className="card-head"><h2>Changes to make</h2>
        <span className="pill">Preview only</span>
        <span className="muted small">Applies to the matched observation only. Nothing is saved to UBM yet.</span></div>
      ${rule.changes.map(c => {
        const setC = p => set({ changes: rule.changes.map(x => x.id === c.id ? Object.assign({}, x, p) : x) });
        return html`<div key=${c.id} className="row chg">
          <span className="lead">Set</span>
          <${Select} value=${c.target} search=${false} options=${present.map(a => ({ value: a.name, label: "Observation " + a.name }))}
            onChange=${v => setC({ target: v })} />
          <${Select} value=${c.field} search=${false} options=${CHANGE_FIELDS.map(f => ({ value: f.id, label: f.label }))}
            onChange=${v => setC({ field: v, value: "" })} />
          <div className="val"><span className="lead to">to</span>
            <${Select} value=${c.value} free=${true} mono=${true} options=${asOpts(values[c.field] || [])}
              placeholder=${c.field === "uom" ? "Choose new unit, e.g. KW or KVA" : "Choose new observation type"}
              onChange=${v => setC({ value: v })} />
          </div>
          <button type="button" className="x" title="Remove change" onClick=${() => set({ changes: rule.changes.filter(x => x.id !== c.id) })}>×</button>
        </div>`;
      })}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ changes: rule.changes.concat([newChange(present[0].name)]) })}>+ Add field change</button></div>
      ${rule.changes.some(c => !c.value) && html`<div className="muted small"><span className="dot warn"></span> Choose a new value to preview the change.</div>`}
    </div>`}

    <div className="bar">
      <span className=${err ? "dot bad" : "dot"}></span>
      <span className=${err ? "err" : "muted"}>${err || (m.custName ? m.custName + " · " : "") + (count ? count + " condition" + (count === 1 ? "" : "s") + " set" : "No conditions yet")}</span>
      <span className="grow"></span>
      <button type="button" className="btn ghost" onClick=${() => setRule(Object.assign(blankRule(), { dateFrom: rule.dateFrom, dateTo: rule.dateTo }))}>Clear all</button>
      <button type="button" className="btn ghost" onClick=${() => showSql ? setShowSql(false) : send("onPreview")}>${showSql ? "Hide SQL" : "Show SQL"}</button>
      <button type="button" className="btn primary" disabled=${running || !m.cust} onClick=${() => send("onRun")}>${running ? "Running…" : "Run query"}</button>
    </div>
    ${showSql && sqlInfo.sql && html`<pre className="sql">${"-- Matching bills\n" + sqlInfo.sql + (sqlInfo.obsSql ? "\n\n-- Matching observations\n" + sqlInfo.obsSql : "")}</pre>`}

    <${Results} res=${res} running=${!!m.running} changes=${rule.changes} />
  </div>`;
}

createRoot(document.getElementById("root")).render(html`<${App} />`);

