:root{
  --bg:var(--appsmith-theme-backgroundColor,#0f172a);
  --surface:var(--appsmith-theme-surfaceColor,#0f172a);
  --card:var(--appsmith-theme-cardColor,#1e293b);
  --alt:var(--appsmith-theme-surfaceAltColor,#1e293b);
  --hover:var(--appsmith-theme-surfaceHoverColor,#26344b);
  --line:var(--appsmith-theme-borderColor,#334155);
  --line2:var(--appsmith-theme-borderMidColor,#475569);
  --strong:var(--appsmith-theme-textStrongColor,#ffffff);
  --text:var(--appsmith-theme-textColor,#e2e8f0);
  --soft:var(--appsmith-theme-textSecondaryColor,#94a3b8);
  --muted:var(--appsmith-theme-textMutedColor,#64748b);
  --link:var(--appsmith-theme-linkColor,#60a5fa);
  --action:var(--appsmith-theme-actionColor,#2563eb);
  --danger:var(--appsmith-theme-dangerColor,#f87171);
  --ok:var(--appsmith-theme-successColor,#34d399);
  --warn:var(--appsmith-theme-warningColor,#fbbf24);
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--surface);color:var(--text);font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;font-size:14px}
#root{height:100%;overflow:auto}
.page{padding:20px 24px 60px;display:flex;flex-direction:column;gap:16px;width:100%}
h1{margin:0 0 4px;font-size:24px;color:var(--strong)}
h2{margin:0;font-size:17px;color:var(--strong)}
.title-row,.card-head,.alias-head,.group-head,.bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.grow{flex:1}
.muted{color:var(--soft)}
.small{font-size:12.5px}
.pad{padding:18px 4px}
.pad-s{padding:10px 8px}
.hint{margin:2px 0 4px}
.err{color:var(--danger)}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12.5px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px 18px;display:flex;flex-direction:column;gap:10px}
.card-head{margin-bottom:4px}

/* inputs and the shared dropdown look the same */
.inp{height:36px;border:1px solid var(--line2);border-radius:6px;background:var(--surface);color:var(--text);padding:0 10px;font:inherit;min-width:0;width:100%}
.inp:focus,.inp:focus-visible{outline:2px solid var(--action);outline-offset:-1px}
.inp:disabled{opacity:.5;cursor:default}
.inp::placeholder{color:var(--muted)}
.inp.date{width:150px}
.sel{position:relative;min-width:0;width:100%}
.sel-btn{display:flex;align-items:center;gap:8px;text-align:left;cursor:pointer}
.sel-btn.ph .sel-txt{color:var(--muted)}
.sel-txt{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.chev{color:var(--muted);font-size:12px}
.pop{position:absolute;z-index:20;top:40px;left:0;min-width:100%;width:max-content;max-width:520px;background:var(--card);border:1px solid var(--line2);border-radius:8px;box-shadow:0 12px 32px rgba(0,0,0,.4);padding:6px;display:flex;flex-direction:column;gap:6px}
.pop-list{max-height:280px;overflow:auto;display:flex;flex-direction:column}
.pop-row{display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:5px;cursor:pointer;color:var(--text);white-space:nowrap}
.pop-row.hi,.pop-row:hover{background:var(--hover)}
.pop-row.on{color:var(--strong);font-weight:700}
.pop-row.on::after{content:"✓";margin-left:auto;color:var(--action)}
.pop-row input{margin:0}
.pop-acts{display:flex;justify-content:space-between;font-size:12.5px;padding:0 4px}
.pop-acts a{color:var(--link);cursor:pointer}
.cnt{margin-left:auto;padding-left:14px;color:var(--muted);font-size:12px}
.pop-row.on .cnt{margin-left:auto}
.w-sm{width:150px}
.w-match{width:220px}
.w-mode{width:240px}
.w-preset{width:340px}

/* rows */
.row{display:grid;grid-template-columns:64px minmax(200px,1.1fr) minmax(170px,.8fr) minmax(240px,1.8fr) 32px;gap:10px;align-items:center}
.row-wrap{display:grid;grid-template-columns:64px 1fr;gap:10px;align-items:start}
.lead{display:inline-flex;justify-content:center;align-items:center;height:32px;border-radius:6px;background:var(--alt);border:1px solid var(--line);color:var(--soft);font-weight:700;font-size:12.5px}
.lead.to{width:40px;flex:none}
.val{display:flex;gap:8px;align-items:center;min-width:0}
.val>.inp,.val>.sel{flex:1}
.val-empty{min-height:36px}
.mode{height:36px;padding:0 9px;border-radius:6px;border:1px dashed var(--line2);background:transparent;color:var(--soft);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap;flex:none}
.mode:hover{color:var(--strong);border-color:var(--soft)}
.x{width:32px;height:32px;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:20px;line-height:1;cursor:pointer}
.x:hover{background:var(--hover);color:var(--danger)}
.group-root{display:flex;flex-direction:column;gap:10px}
.group{border:1px dashed var(--line2);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:10px;background:rgba(127,127,127,.04)}
.adds{display:flex;gap:10px;flex-wrap:wrap}

/* buttons */
.btn{height:36px;padding:0 14px;border-radius:6px;font:inherit;font-weight:600;cursor:pointer;border:1px solid var(--line2);background:transparent;color:var(--text);white-space:nowrap}
