.dot{width:9px;height:9px;border-radius:50%;background:var(--ok);display:inline-block}
.dot.bad{background:var(--danger)}
.dot.warn{background:var(--warn);margin-right:6px;vertical-align:middle}
.sql{margin:0;padding:14px;border-radius:8px;background:var(--surface);border:1px solid var(--line);color:var(--soft);white-space:pre-wrap;word-break:break-word;font-family:ui-monospace,Menlo,monospace;font-size:12px;max-height:340px;overflow:auto}

/* results */
.tabs{display:flex;gap:4px;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:3px}
.tab{height:30px;padding:0 12px;border:0;border-radius:6px;background:transparent;color:var(--soft);font:inherit;font-weight:600;cursor:pointer}
.tab.on{background:var(--action);color:#fff}
.tbl-wrap{overflow:auto;max-height:600px;border:1px solid var(--line);border-radius:8px}
.tbl{width:100%;border-collapse:collapse}
.tbl th{position:sticky;top:0;background:var(--alt);text-align:left;padding:10px 14px;color:var(--soft);font-size:12.5px;font-weight:700;white-space:nowrap;border-bottom:1px solid var(--line)}
.tbl td{padding:9px 14px;border-bottom:1px solid var(--line);white-space:nowrap;max-width:320px;overflow:hidden;text-overflow:ellipsis}
.tbl tr:hover td{background:var(--hover)}
.num{text-align:right}
.link{color:var(--link);cursor:pointer;font-weight:600}
.link:hover{text-decoration:underline}
